package vn.hust.restaurant.view;
import java.awt.*;import javax.swing.*;import vn.hust.restaurant.config.*;import vn.hust.restaurant.model.UserSession;
public class LoginFrame extends JFrame{private final AppContext ctx;private final JTextField user=new JTextField("admin",20);private final JPasswordField pass=new JPasswordField("123456",20);public LoginFrame(AppContext c){super(AppConfig.app("restaurant.name","HTQL Nhà hàng")+" - Đăng nhập");ctx=c;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(460,330);setLocationRelativeTo(null);build();}
 private void build(){JPanel form=new JPanel(new GridBagLayout());form.setBorder(BorderFactory.createEmptyBorder(25,35,25,35));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(8,8,8,8);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("HỆ THỐNG QUẢN LÝ NHÀ HÀNG",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(Font.BOLD,20));form.add(title,g);g.gridwidth=1;g.gridy++;form.add(new JLabel("Tên đăng nhập"),g);g.gridx=1;form.add(user,g);g.gridx=0;g.gridy++;form.add(new JLabel("Mật khẩu"),g);g.gridx=1;form.add(pass,g);JButton login=new JButton("Đăng nhập");JButton forgot=new JButton("Quên mật khẩu");g.gridx=0;g.gridy++;g.gridwidth=2;form.add(login,g);g.gridy++;form.add(forgot,g);JLabel db=new JLabel(Database.testConnection()?"Đã kết nối SQL Server":"Chưa kết nối SQL Server - kiểm tra database.properties",SwingConstants.CENTER);g.gridy++;form.add(db,g);setContentPane(form);getRootPane().setDefaultButton(login);login.addActionListener(e->doLogin());forgot.addActionListener(e->new ForgotPasswordDialog(this,ctx).setVisible(true));}
 private void doLogin(){Ui.run(this,()->{UserSession s=ctx.auth.login(user.getText(),pass.getPassword());dispose();new MainFrame(ctx,s).setVisible(true);});}
}
